// ============================================================
// VALIDATE INPUT for attribute creation
// ============================================================
// Required: name (string)
// Optional: slug (string), type (string), order_by (string)

const items = $input.all();
const body = items[0]?.json?.body || items[0]?.json || {};

const name = (body.name || '').trim();
const slug = (body.slug || '').trim();
const type = (body.type || 'select').trim();
const orderBy = (body.order_by || 'menu_order').trim();

if (!name) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: 'Attribute name is required.'
      }
    }
  }];
}

// Validate type value
const validTypes = ['select', 'text'];
if (!validTypes.includes(type)) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: 'Invalid attribute type. Must be one of: ' + validTypes.join(', ')
      }
    }
  }];
}

// Validate order_by value
const validOrderBy = ['menu_order', 'name', 'name_num', 'id'];
if (!validOrderBy.includes(orderBy)) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: 'Invalid order_by. Must be one of: ' + validOrderBy.join(', ')
      }
    }
  }];
}

return [{
  json: {
    _valid: true,
    name: name,
    slug: slug || '',
    type: type,
    order_by: orderBy
  }
}];

// ============================================================
// FORMAT ATTRIBUTE CREATION RESPONSE
// ============================================================
// Handle success, duplicate (attribute already exists), and errors.

const items = $input.all();
const data = items[0]?.json || {};

// Successful creation — WooCommerce returns the new attribute object
if (data.id && data.name) {
  return [{
    json: {
      success: true,
      attribute: {
        id: data.id,
        name: data.name,
        slug: data.slug || '',
        type: data.type || 'select',
        order_by: data.order_by || 'menu_order'
      }
    }
  }];
}

// WooCommerce error: attribute already exists
if (data.code === 'woocommerce_rest_cannot_create' || 
    (data.message && data.message.toLowerCase().includes('already exists'))) {
  return [{
    json: {
      success: false,
      message: 'An attribute with this name already exists.',
      code: data.code || 'attribute_exists'
    }
  }];
}

// Other error
return [{
  json: {
    success: false,
    message: data.message || 'Failed to create attribute.'
  }
}];

// Pass through the validation error as the response
const items = $input.all();
return [{ json: items[0].json._error }];
